fn put(o:&mut[u8],p:usize,x:f64){o[p..p+8].copy_from_slice(&x.to_le_bytes());}
#[no_mangle]
pub unsafe extern "C" fn gaussian_elimination_pivoting(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<1||n>21{return -1}let vals=std::slice::from_raw_parts(v,n);let d=vals[0];if !(2..=4).contains(&d)||n!=1+(d*(d+1))as usize{return -1}let d=d as usize;let mut a=[[0.0f64;5];4];for i in 0..d{for j in 0..=d{let z=vals[1+i*(d+1)+j];if !(-10000..=10000).contains(&z){return -1}a[i][j]=z as f64/1000.0;}}let bytes=d*8;for col in 0..d{for i in col..d{if a[i][col].abs()>a[col][col].abs(){a.swap(col,i);}}if a[col][col].abs()<1e-8{return -1}if col!=0{let prior=col-1;for i in col..d{let f=a[i][prior]/a[prior][prior];for j in 0..=d{a[i][j]-=f*a[prior][j];}}}}let mut x=[0.0;4];for col in (0..d).rev(){x[col]=a[col][d]/a[col][col];for i in (0..col).rev(){a[i][d]-=a[i][col]*x[col];}}if out.is_null()||cap<bytes{return -2}let dst=std::slice::from_raw_parts_mut(out,bytes);for i in 0..d{put(dst,i*8,x[i]);}bytes as i64}
